use vstd::prelude::*;

verus! {
    fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> (result: Vec<f32>)
        ensures
            result.len() == arr.len() + values.len(),
            forall|i: nat| (i < arr.len() ==> result[i] == arr[i]),
            forall|j: nat| (j < values.len() ==> result[arr.len() + j] == values[j]),
    {
        let mut result: Vec<f32> = Vec::new();
        let mut i: nat = 0;
        let arr_len: nat = arr.len() as nat;
        let values_len: nat = values.len() as nat;

        // Append elements from the first vector
        while i < arr_len
            invariant
                i <= arr_len,
                result.len() == i,
                forall|k: nat| (k < i ==> result[k] == arr[k]),
            decreases arr_len - i,
        {
            result.push(arr[i]);
            i = i + 1;
        }

        // Append elements from the second vector
        let mut j: nat = 0;
        while j < values_len
            invariant
                j <= values_len,
                result.len() == arr_len + j,
                forall|k: nat| (k < arr_len ==> result[k] == arr[k]),
                forall|k: nat| (k < j ==> result[arr_len + k] == values[k]),
            decreases values_len - j,
        {
            result.push(values[j]);
            j = j + 1;
        }

        result
    }
}

